import{_ as t,o as a,c as i,ag as l}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"UncivCN Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Changelog.md","filePath":"UncivCN/Changelog.md"}'),o={name:"UncivCN/Changelog.md"};function n(r,e,s,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="uncivcn-changelog" tabindex="-1">UncivCN Changelog <a class="header-anchor" href="#uncivcn-changelog" aria-label="Permalink to &quot;UncivCN Changelog&quot;">​</a></h1><p>Version rule: upstream version + CN sub-version (<code>.1</code>, <code>.2</code>, <code>.3</code>…; the same upstream version can have multiple CN sub-versions, e.g. 4.20.8.1 → 4.20.8.4; restarts at <code>.1</code> after merging a new upstream, e.g. 4.21.5 → 4.21.5.1).</p><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><ul><li>Fixed the docs site showing unstyled text under the custom domain: site artifacts are now deployed to the <code>Unciv/</code> subdirectory with a root redirect page</li><li>Fixed duplicate <code>/Unciv</code> prefix in the navbar logo path</li><li>In-game version display is now synced automatically from <code>BuildConfig.kt</code> to <code>UncivGame.kt</code> at build time (previously a manual release could forget this and ship a stale in-game version)</li><li>Slimmed down <code>AGENTS.md</code> to behavior rules only; development reference (build commands, project structure, game state model, assets) moved into Coding-standards, which is now the engineering handbook (bilingual)</li></ul><h2 id="v4-21-5-3-build-1244" tabindex="-1">v4.21.5.3 (build 1244) <a class="header-anchor" href="#v4-21-5-3-build-1244" aria-label="Permalink to &quot;v4.21.5.3 (build 1244)&quot;">​</a></h2><ul><li>Fixed CI test failures: 13 translation templates were missing the trailing space (breaking <code>TranslationTests</code>); test mods <code>testMOD</code> / <code>testMapScript</code> are now tracked in the repo (previously git-ignored, which broke Lua-script and merge-action tests in CI), with <code>testMOD/jsons/Buildings.json</code> added</li><li>Deploy workflow no longer posts release announcements to Discord (GitHub Release upload kept)</li></ul><h2 id="v4-21-5-2-build-1243" tabindex="-1">v4.21.5.2 (build 1243) <a class="header-anchor" href="#v4-21-5-2-build-1243" aria-label="Permalink to &quot;v4.21.5.2 (build 1243)&quot;">​</a></h2><ul><li>Official docs site launched: a brand-new VitePress site (replacing mkdocs) with full-text Chinese search, one-click EN/CN switching, and one-click copy on unique listings <ul><li>The English section fully reuses upstream docs; the Chinese section is a complete translation mirror (Modders / Developers / Translating / Other and all other pages)</li><li>New UncivCN section (about / features / changelog / differences / coding standards / polling multiplayer) and community section (guides / mods / code analysis / upstream changelog), all bilingual</li></ul></li><li>Unique documentation now in Chinese: new <code>docDescriptionZh</code> mechanism — modders can read Chinese explanations of uniques on the docs site</li><li>Build &amp; release pipeline adapted: local APK signing (zipalign + apksigner V3), artifacts named UncivCN; new signing regression CI</li></ul><h2 id="v4-21-5-1-build-1242" tabindex="-1">v4.21.5.1 (build 1242) <a class="header-anchor" href="#v4-21-5-1-build-1242" aria-label="Permalink to &quot;v4.21.5.1 (build 1242)&quot;">​</a></h2><ul><li>Merged upstream 4.21.5 (AI gold/war logic fixes, CPU performance improvements, city-state start optimizations, etc.; see upstream <a href="https://github.com/AutumnPizazz/Unciv/blob/UncivCN/changelog.md" target="_blank" rel="noreferrer">changelog.md</a>)</li><li>Reverted the bundled UCCC mod — the game no longer bundles any mods</li><li>New: export/import new game settings to clipboard</li><li>Adjusted the citizen auto-lock button logic</li><li>Fixed a stats-display cascade bug, aligned with upstream master</li></ul><h2 id="v4-21-0-2-2026-08-01" tabindex="-1">v4.21.0.2 (2026-08-01) <a class="header-anchor" href="#v4-21-0-2-2026-08-01" aria-label="Permalink to &quot;v4.21.0.2 (2026-08-01)&quot;">​</a></h2><ul><li>Fixed some UCCC mod bugs</li></ul><h2 id="v4-21-0-1-2026-08-01" tabindex="-1">v4.21.0.1 (2026-08-01) <a class="header-anchor" href="#v4-21-0-1-2026-08-01" aria-label="Permalink to &quot;v4.21.0.1 (2026-08-01)&quot;">​</a></h2><ul><li>Followed recent upstream updates (incl. symmetric/mirror maps, stats panel merged from upstream)</li><li>Since both branches made similar changes to the victory panel, reverted &quot;disable experimental stats panel when civ-score panel is disabled&quot; — upstream wins</li><li>Completed missing Chinese localization</li><li>Default multiplayer server changed to <code>http://sp.unciv.cn:30123</code></li><li>New citizen auto-lock shortcut button (&quot;Auto lock&quot; at the bottom-right of the city screen; permanently toggles unlocked/locked citizens)</li><li>Bundled the UCCC mod</li><li>RNG re-roll on load no longer available in multiplayer</li></ul><h2 id="v4-20-17-2-2026-07-12" tabindex="-1">v4.20.17.2 (2026-07-12) <a class="header-anchor" href="#v4-20-17-2-2026-07-12" aria-label="Permalink to &quot;v4.20.17.2 (2026-07-12)&quot;">​</a></h2><ul><li>New unit pins / map pins features (see <a href="./Features.html#unit-pins--map-pins-420172">Features</a>)</li><li>Lifted the radius parity restriction for rotationally symmetric maps</li><li>Disabling the civ-score panel also disables the experimental stats panel</li><li>Save version isolation (old clients can&#39;t load new saves)</li><li>Citizens no longer starve when training settlers and other food→production units</li></ul><h2 id="v4-20-17-1-2026-07-04" tabindex="-1">v4.20.17.1 (2026-07-04) <a class="header-anchor" href="#v4-20-17-1-2026-07-04" aria-label="Permalink to &quot;v4.20.17.1 (2026-07-04)&quot;">​</a></h2><ul><li>Followed over a month of upstream updates</li></ul><h2 id="v4-20-8-4-2026-05-26" tabindex="-1">v4.20.8.4 (2026-05-26) <a class="header-anchor" href="#v4-20-8-4-2026-05-26" aria-label="Permalink to &quot;v4.20.8.4 (2026-05-26)&quot;">​</a></h2><ul><li>The built-in mod checker can lint Lua errors in mods</li><li>Polling multiplayer shows other players&#39; online status</li></ul><h2 id="v4-20-8-3-2026-05-23" tabindex="-1">v4.20.8.3 (2026-05-23) <a class="header-anchor" href="#v4-20-8-3-2026-05-23" aria-label="Permalink to &quot;v4.20.8.3 (2026-05-23)&quot;">​</a></h2><ul><li>Enhanced the Lua system</li><li>Events can be hooked with Lua</li></ul><h2 id="v4-20-8-2-2026-05-22" tabindex="-1">v4.20.8.2 (2026-05-22) <a class="header-anchor" href="#v4-20-8-2-2026-05-22" aria-label="Permalink to &quot;v4.20.8.2 (2026-05-22)&quot;">​</a></h2><ul><li>Mods support <a href="/Unciv/Modders/Lua-Modding.html">Lua scripting</a></li><li>Fixed a bug where the &quot;Elite Education&quot; policy in Gods &amp; Kings didn&#39;t grant great people</li><li>Amount parameters accept Countables; several new Countables parameter types</li><li>Fixed a bug where TRY_INJECT units had their cost overwritten to 0</li></ul><h2 id="v4-20-8-1-2026-05-21" tabindex="-1">v4.20.8.1 (2026-05-21) <a class="header-anchor" href="#v4-20-8-1-2026-05-21" aria-label="Permalink to &quot;v4.20.8.1 (2026-05-21)&quot;">​</a></h2><ul><li>Major: new <a href="./Polling-multiplayer.html">polling multiplayer</a></li></ul><h2 id="v4-20-7-4-2026-05-19" tabindex="-1">v4.20.7.4 (2026-05-19) <a class="header-anchor" href="#v4-20-7-4-2026-05-19" aria-label="Permalink to &quot;v4.20.7.4 (2026-05-19)&quot;">​</a></h2><ul><li>Center-symmetric maps now distribute resources symmetrically too</li></ul><h2 id="v4-20-7-3-2026-05-19" tabindex="-1">v4.20.7.3 (2026-05-19) <a class="header-anchor" href="#v4-20-7-3-2026-05-19" aria-label="Permalink to &quot;v4.20.7.3 (2026-05-19)&quot;">​</a></h2><ul><li>Extended the mod JSON system; see <a href="/Unciv/Modders/Mod-file-structure/6-MergeActions.html">MergeAction tutorial</a></li></ul><hr><h2 id="v4-20-7-2" tabindex="-1">v4.20.7.2 <a class="header-anchor" href="#v4-20-7-2" aria-label="Permalink to &quot;v4.20.7.2&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-19</p><ul><li>Android builds no longer bundle the CoeHarMod mod</li><li>New three mirrored map modes, center-symmetric in 2/3/6-fold patterns</li></ul><h2 id="v4-20-6-3" tabindex="-1">v4.20.6.3 <a class="header-anchor" href="#v4-20-6-3" aria-label="Permalink to &quot;v4.20.6.3&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-17</p><ul><li>New mod features:</li></ul><table tabindex="0"><thead><tr><th>English text</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Hidden from city screen</code></td><td>No longer shown in the city panel</td></tr><tr><td><code>Can be built [amount] times in each city</code></td><td>Can be built [amount] times in a single city</td></tr></tbody></table><h2 id="v4-20-6-1" tabindex="-1">v4.20.6.1 <a class="header-anchor" href="#v4-20-6-1" aria-label="Permalink to &quot;v4.20.6.1&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-16</p><ul><li>Synced two months of upstream updates</li><li>Folded the previous random-result-variability changes into a settings toggle</li></ul><h2 id="v4-19-16-2" tabindex="-1">v4.19.16.2 <a class="header-anchor" href="#v4-19-16-2" aria-label="Permalink to &quot;v4.19.16.2&quot;">​</a></h2><p><strong>Released</strong>: 2026-03-02</p><ul><li>Ancient-ruin random results can be re-rolled by reloading a save</li></ul><h2 id="v4-19-16-1" tabindex="-1">v4.19.16.1 <a class="header-anchor" href="#v4-19-16-1" aria-label="Permalink to &quot;v4.19.16.1&quot;">​</a></h2><p><strong>Released</strong>: 2026-03-01</p><ul><li>City-state quest random results can be re-rolled by reloading a save</li></ul><h2 id="v4-19-15-cn2" tabindex="-1">v4.19.15-cn2 <a class="header-anchor" href="#v4-19-15-cn2" aria-label="Permalink to &quot;v4.19.15-cn2&quot;">​</a></h2><p><strong>Released</strong>: 2026-02-28</p><ul><li>New mod features:</li></ul><table tabindex="0"><thead><tr><th>English text</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Attacks also target [mapUnitFilter] units within [positiveAmount] tiles</code></td><td>Attacks also hit [mapUnitFilter] units within [positiveAmount] tiles</td></tr><tr><td><code>Attacks also target [mapUnitFilter] units within [positiveAmount] tiles, with damage decreasing by distance</code></td><td>Attacks also hit [mapUnitFilter] units within [positiveAmount] tiles, damage decreasing with distance</td></tr><tr><td><code>Takes [relativeAmount]% damage from own area attacks</code></td><td>Takes only [relativeAmount]% damage from its own area attacks</td></tr><tr><td><code>Takes [relativeAmount]% counter damage from each unit hit by its area attacks</code></td><td>Takes [relativeAmount]% counter damage from each unit hit by its area attacks</td></tr></tbody></table><ul><li>Added stats panel data export to CSV</li></ul><h2 id="v4-19-15" tabindex="-1">v4.19.15 <a class="header-anchor" href="#v4-19-15" aria-label="Permalink to &quot;v4.19.15&quot;">​</a></h2><p><strong>Released</strong>: 2026-02-26</p><ul><li>Android builds bundled the <a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">CoeHarMod</a> mod</li><li>Adjacent cities can swap tiles; mods must declare the unique &quot;Allow cities to claim tiles&quot; in their ModOptions.json</li></ul>',55)])])}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
